const loadLocal=():Catalog=>{try{const recovered=(window as any).__CATALOGO_BOOT_CATALOG__;if(recovered&&typeof recovered==='object')return normalizeCatalog(recovered);return normalizeCatalog(JSON.parse(localStorage.getItem(key)||'null')||seed)}catch{return seed}};
const openCatalogDB=():Promise<IDBDatabase>=>new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(new Error('IndexedDB no disponible'));return}const request=indexedDB.open('catalogo-facil-recovery-v1',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('catalogs'))request.result.createObjectStore('catalogs')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('No se pudo abrir la base local'))});
const storeCatalogDB=async(catalog:any)=>{const db=await openCatalogDB();try{await new Promise<void>((resolve,reject)=>{const tx=db.transaction('catalogs','readwrite');tx.objectStore('catalogs').put(catalog,'current');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||new Error('No se pudo guardar el catálogo en IndexedDB'));tx.onabort=()=>reject(tx.error||new Error('Guardado local cancelado'))})}finally{db.close()}};
const clearCatalogDB=async()=>{const db=await openCatalogDB();try{await new Promise<void>((resolve,reject)=>{const tx=db.transaction('catalogs','readwrite');tx.objectStore('catalogs').delete('current');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||new Error('No se pudo limpiar la copia local'))})}finally{db.close()}};
const readCatalogDB=async()=>{const db=await openCatalogDB();const value=await new Promise<any>((resolve,reject)=>{const tx=db.transaction('catalogs','readonly');const request=tx.objectStore('catalogs').get('current');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('No se pudo leer el catálogo local'))});db.close();return value};
const isPlaceholder=(value:any,kind:'product'|'category')=>{const v=String(value??'').trim().toLocaleLowerCase('es');return !v|| (kind==='product'?/^(nuevo producto|producto nuevo|new product|sin nombre|producto)$/.test(v):/^(nueva categoría|nueva categoria|categoría nueva|categoria nueva|new category|sin nombre)$/.test(v))};
// La importación y recuperación nunca deben descartar productos/categorías por criterios visuales: los respaldos antiguos pueden tener relaciones incompletas y aun así contener datos valiosos. Normalizamos solo la estructura, conservando todos los registros originales válidos.
const cleanCatalog=(raw:any)=>{const x={...seed,...(raw&&typeof raw==='object'?raw:{})};const normalizedCategories=(Array.isArray(x.categories)?x.categories:[]).filter((v:any)=>v&&typeof v==='object').map((v:any)=>({...v,id:String(v.id||uid()),name:String(v.name??'').trim(),emoji:String(v.emoji||'📦')}));const normalizedProducts=(Array.isArray(x.products)?x.products:[]).filter((v:any)=>v&&typeof v==='object'&&!Array.isArray(v)).map((v:any)=>({...v,id:String(v.id||uid()),name:String(v.name??'').trim(),description:String(v.description??'').slice(0,200),category:String(v.category??''),image:typeof v.image==='string'?v.image:'',price:Number.isFinite(Number(v.price))?Number(v.price):0,available:v.available!==false,usesVariants:Boolean(v.usesVariants),sizes:Array.isArray(v.sizes)?v.sizes.map((z:any)=>String(z)).filter(Boolean):[],colors:Array.isArray(v.colors)?v.colors.map((z:any)=>String(z)).filter(Boolean):[],colorOptions:Array.isArray(v.colorOptions)?v.colorOptions.filter((z:any)=>z&&typeof z==='object').map((z:any)=>({...z,name:String(z.name||'Color'),value:String(z.value||'#888888'),value2:String(z.value2||z.value||'#888888'),gradient:Boolean(z.gradient)})):[]}));const products=normalizedProducts.filter((p:any)=>!isPlaceholder(p.name,'product')||Boolean(p.image.trim())||Boolean(p.description.trim())||p.price>0);const categories=normalizedCategories.filter((cat:any)=>!isPlaceholder(cat.name,'category'));const validCategoryIds=new Set(categories.map((cat:any)=>cat.id));const cleanedProducts=products.map((p:any)=>validCategoryIds.has(p.category)?p:{...p,category:''});return {...x,categories,products:cleanedProducts};};
const normalizeCatalog=(raw:any):Catalog=>{
 const x=cleanCatalog(raw);
 return {...x,titleEffect:normEffect(x.titleEffect,'elegante'),priceEffect:normEffect(x.priceEffect,'oro'),theme:((['classic','luxury','neon','minimal','food','glass','market','vintage','pastel','industrial','botanical','bold','ocean','sunset','lavender','candy','emerald','coral','arctic','midnight','royal','desert','rose','cyber','mono','citrus','coffee','berry','sky','terra','aurora','pearl','carbon','neon-pink','neon-blue','neon-purple','neon-lime','neon-cyber','glass-neon','holographic','electric','matrix','ultraviolet'].includes(x.theme) || /^(custom|claude)-[a-z0-9-]+$/.test(String(x.theme||''))) ? x.theme : 'classic') as Theme,font:(['system','inter','montserrat','playfair','nunito','space','manrope','outfit','dm','orbitron','poppins','roboto','lato','raleway','oswald','rubik','quicksand','comfortaa','bebas','anton','abril','cinzel','cormorant','lora','merriweather','dmserif','josefin','worksans','syne','sora','urbanist','lexend','bricolage','fraunces','righteous','audiowide','exo2','pacifico'].includes(x.font)?x.font:'system') as Font,shape:(['square','soft','round','pill'].includes(x.shape)?x.shape:'soft') as Shape,coverShape:(['square','soft','round','pill'].includes(x.coverShape)?x.coverShape:(x.shape||'round')) as Shape,productShape:(['square','soft','round','pill'].includes(x.productShape)?x.productShape:(x.shape||'soft')) as Shape,titleSize:Math.max(22,Math.min(64,Number(x.titleSize)||38)),descriptionSize:Math.max(12,Math.min(30,Number(x.descriptionSize)||16)),categories:Array.isArray(x.categories)?x.categories:seed.categories,products:Array.isArray(x.products)?x.products:[]};
};
