const API_BASE=String((window as any).CATALOGO_FACIL_API||'https://catalogo-facil-publisher.francoferrari9595.workers.dev').trim().replace(/\/$/,'');
async function publishCatalog(data:any,slug:string,password:string){
 if(!API_BASE)throw new Error('El publicador todavía no está configurado. Ejecutá CONFIGURAR_PUBLICADOR.bat una sola vez.');
 const r=await fetch(`${API_BASE}/publish`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slug,catalog:data,password})});
 let out:any={};try{out=await r.json()}catch{}
 if(!r.ok||!out.ok)throw new Error(out.error||`El publicador respondió con ${r.status}.`);
 return out;
}
async function passwordHash(password:string,salt:string){const bytes=new TextEncoder().encode(`${salt}:${password}`);const digest=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('')}
async function loadPublishedCatalog(slug:string){
 if(!API_BASE)throw new Error('El publicador todavía no está configurado.');
 const r=await fetch(`${API_BASE}/catalog/${encodeURIComponent(slug)}?editor=1&ts=${Date.now()}`,{cache:'no-store'});
 let data:any={};try{data=await r.json()}catch{}
 if(!r.ok){const e:any=new Error(data.error||'No se encontró el catálogo publicado.');e.expired=Boolean(data.expired);e.supportWhatsApp=data.supportWhatsApp||'2615407856';e.supportEmail=data.supportEmail||'francoferrari95@gmail.com';throw e}
 return data;
}
function adminDateValue(v:string){if(!v)return '';const d=new Date(v);if(!Number.isFinite(d.getTime()))return '';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Argentina/Buenos_Aires',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const get=(t:string)=>parts.find(p=>p.type===t)?.value||'';return `${get('year')}-${get('month')}-${get('day')}`;}

class AppErrorBoundary extends React.Component<{children:React.ReactNode},{failed:boolean,error:string,message:string,busy:boolean}>{
 constructor(props:{children:React.ReactNode}){super(props);this.state={failed:false,error:'',message:'',busy:false}}
 static getDerivedStateFromError(error:Error){return {failed:true,error:String(error?.message||error||'Error de interfaz')}}
 componentDidCatch(error:Error){console.error('Catálogo Fácil recuperó un error de pantalla:',error)}
 resetLocalEditor=async()=>{try{localStorage.removeItem(key);await clearCatalogDB();this.setState({message:'Se limpió únicamente la copia local dañada. El catálogo publicado en la nube no se modifica.'});setTimeout(()=>location.reload(),450)}catch(e:any){this.setState({message:'No se pudo limpiar la copia local: '+String(e?.message||e)})}}
 loadCloud=async()=>{const answer=prompt('Pegá el enlace publicado o el identificador del catálogo. Ejemplo: pepperina-s-indumentaria');if(!answer)return;let target=answer.trim();try{if(/^https?:\/\//i.test(target)){const u=new URL(target);target=u.searchParams.get('catalog')||u.pathname.match(/\/catalog\/([^/]+)/)?.[1]||u.pathname.split('/').filter(Boolean).pop()||''}}catch{}try{target=slugify(decodeURIComponent(target.replace(/^\/+|\/+$/g,'')))}catch{}if(!target){this.setState({message:'No pude reconocer el identificador del catálogo.'});return}this.setState({busy:true,message:`Recuperando ${target} desde la nube…`});try{const remote=await loadPublishedCatalog(target);const cleaned=normalizeCatalog(remote);const serialized=JSON.stringify(cleaned);await storeCatalogDB(cleaned);try{localStorage.setItem(key,serialized)}catch(storageError){console.warn('El catálogo es grande para localStorage; se conservará en IndexedDB.',storageError)}try{localStorage.setItem('catalogo-facil-recovery-slug',target)}catch{}this.setState({message:`Catálogo descargado: ${cleaned.name||target} · ${cleaned.products.length} productos. Se guardó una copia local; el editor se volverá a abrir.`});setTimeout(()=>location.href=location.pathname,700)}catch(e:any){this.setState({message:`No se pudo recuperar ${target}: ${e?.message||'error de conexión'}`})}finally{this.setState({busy:false})}}
 importBackup=()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json,.catalogo.json';input.onchange=()=>{const f=input.files?.[0];if(!f)return;const reader=new FileReader();reader.onerror=()=>this.setState({message:'No se pudo leer el archivo. El respaldo original no se modificó.'});reader.onload=async()=>{try{const raw=JSON.parse(String(reader.result));if(!raw||typeof raw!=='object'||(!Array.isArray(raw.products)&&!Array.isArray(raw.categories)))throw new Error('El archivo no tiene la estructura de un catálogo.');const cleaned=normalizeCatalog(raw);await storeCatalogDB(cleaned);try{localStorage.setItem(key,JSON.stringify(cleaned))}catch{}if(raw.slug)try{localStorage.setItem('catalogo-facil-recovery-slug',String(raw.slug))}catch{}this.setState({message:`Respaldo cargado: ${cleaned.name||'Catálogo'} · ${cleaned.products.length} productos. El editor se abrirá nuevamente.`});setTimeout(()=>location.href=location.pathname,700)}catch(e:any){this.setState({message:`No se pudo cargar el respaldo: ${e?.message||'error'}. El archivo original sigue intacto.`})}};reader.readAsText(f,'UTF-8')};input.click()}
 downloadLocal=async()=>{try{let raw:any=localStorage.getItem(key);if(!raw){const saved=await readCatalogDB();if(saved)raw=JSON.stringify(saved)}if(!raw){this.setState({message:'No hay una copia local guardada para descargar.'});return}const blob=new Blob([typeof raw==='string'?raw:JSON.stringify(raw,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='catalogo-facil-respaldo-local.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);this.setState({message:'Se descargó la copia local disponible.'})}catch(e:any){this.setState({message:'No se pudo descargar la copia local: '+String(e?.message||e)})}}
 render(){if(this.state.failed)return <div style={{minHeight:'100vh',display:'grid',placeItems:'center',padding:18,background:'#09090f',color:'#fff',fontFamily:'system-ui'}}><section style={{width:'min(100%,620px)',padding:24,border:'1px solid #45405a',borderRadius:20,background:'#171522',boxSizing:'border-box'}}><h1 style={{marginTop:0,fontSize:28}}>Recuperación del editor</h1><p>El editor encontró un error y se detuvo para proteger los datos. El catálogo publicado no se borra. Desde acá podés recuperar el catálogo de la nube o importar un respaldo sin depender de la pantalla principal.</p><details style={{margin:'12px 0',color:'#c4b5fd'}}><summary>Detalles técnicos del error</summary><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{this.state.error}</pre></details><div style={{display:'grid',gap:10}}><button disabled={this.state.busy} style={{padding:14,border:0,borderRadius:10,fontWeight:800}} onClick={()=>void this.loadCloud()}>{this.state.busy?'Recuperando…':'Cargar catálogo publicado desde la nube'}</button><button style={{padding:14,border:'1px solid #57516a',borderRadius:10,background:'#242033',color:'#fff',fontWeight:700}} onClick={this.importBackup}>Cargar respaldo JSON desde el dispositivo</button><button style={{padding:14,border:'1px solid #57516a',borderRadius:10,background:'#242033',color:'#fff',fontWeight:700}} onClick={this.downloadLocal}>Descargar copia local disponible</button><button style={{padding:14,border:'1px solid #57516a',borderRadius:10,background:'#242033',color:'#fff',fontWeight:700}} onClick={this.resetLocalEditor}>Abrir editor limpio (no borra la nube)</button><button style={{padding:12,border:0,borderRadius:10,background:'#fff',color:'#111',fontWeight:800}} onClick={()=>location.reload()}>Volver a cargar</button></div>{this.state.message&&<p role="status" style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere',padding:12,borderRadius:10,background:'#0d0c13',lineHeight:1.5}}>{this.state.message}</p>}<small style={{color:'#b5b1c4'}}>“Abrir editor limpio” elimina solamente el borrador local de este navegador. No elimina catálogos publicados ni modifica Cloudflare.</small></section></div>;return this.props.children}}


function App(){
 const params=new URLSearchParams(location.search);const publicSlug=params.get('catalog');
 if(params.get('admin')==='1')return <AdminPanel/>;
 if(publicSlug)return <PublicCatalog slug={publicSlug}/>;
 if(params.has('directory'))return <Directory api={API_BASE}/>;
 return <CatalogStudio/>;
}

function AdminPanel(){const[key,setKey]=useState('');const[items,setItems]=useState<any[]>([]);const[msg,setMsg]=useState('');const[loaded,setLoaded]=useState(false);const[alertDrafts,setAlertDrafts]=useState<Record<string,string>>({});const call=async(path:string,method='GET',body?:any)=>{if(!API_BASE)throw new Error('Falta la URL del publicador. Revisá public/api-config.js y volvé a publicar el sitio.');const r=await fetch(`${API_BASE}${path}`,{method,headers:{'Content-Type':'application/json','X-Admin-Key':key},body:body?JSON.stringify(body):undefined});let d:any={};try{d=await r.json()}catch{}if(!r.ok||!d.ok){const detail=d.error||`El publicador respondió HTTP ${r.status}.`;if(r.status===404&&String(detail).toLowerCase().includes('ruta administrativa'))throw new Error('El Worker de Cloudflare todavía tiene una versión anterior. Actualizá publisher/worker.js desde este ZIP y presioná Deploy; conservá CATALOGS y ADMIN_KEY.');throw new Error(detail)}return d};const refresh=async()=>{try{const d=await call('/admin/catalogs');setItems(d.catalogs||[]);setAlertDrafts(Object.fromEntries((d.catalogs||[]).map((x:any)=>[x.slug,x.alertMessage||''])));setLoaded(true);setMsg('Lista actualizada.')}catch(e:any){setMsg(e.message)}};const setMonths=async(x:any,months:number)=>{try{const d=new Date();d.setMonth(d.getMonth()+months);const localDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;await call('/admin/catalogs/expiry','POST',{slug:x.slug,expiresAt:localDate});await refresh();setMsg(`Vencimiento guardado para ${x.name}: ${localDate.split('-').reverse().join('/')}.`)}catch(e:any){setMsg(e.message)}};const setDate=async(x:any,value:string)=>{try{await call('/admin/catalogs/expiry','POST',{slug:x.slug,expiresAt:value||null});await refresh();setMsg(value?`Vencimiento guardado para ${x.name}: ${value.split('-').reverse().join('/')}.`:`Se quitó el vencimiento de ${x.name}.`)}catch(e:any){setMsg(e.message)}};const saveAlert=async(x:any)=>{try{const message=(alertDrafts[x.slug]||'Por favor efectuar pago WhatsApp 2615407856').trim();await call('/admin/catalogs/alert','POST',{slug:x.slug,message});await refresh();setMsg(`Alerta enviada al catálogo ${x.name}.`)}catch(e:any){setMsg(e.message)}};const setStatus=async(x:any,status:string)=>{try{await call('/admin/catalogs/status','POST',{slug:x.slug,status});await refresh();setMsg(status==='active'?`Catálogo ${x.name} aprobado y visible.`:status==='rejected'?`Se rechazó la solicitud de ${x.name}.`:`Estado actualizado: ${x.name}.`)}catch(e:any){setMsg(e.message)}};const exportJson=async(x:any)=>{try{const r=await fetch(`${API_BASE}/admin/catalogs/export?slug=${encodeURIComponent(x.slug)}`,{headers:{'X-Admin-Key':key}});if(!r.ok){let d:any={};try{d=await r.json()}catch{}throw new Error(d.error||(r.status===404?'El Worker publicado no tiene la ruta de descarga JSON. Actualizá publisher/worker.js y hacé Deploy.':`No se pudo descargar (${r.status}).`))}const blob=await r.blob();if(!blob.size)throw new Error('El respaldo descargado está vacío.');const filename=`${x.slug}.json`;const nav:any=navigator;if(nav.msSaveOrOpenBlob){nav.msSaveOrOpenBlob(blob,filename)}else{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;a.rel='noopener';a.style.position='fixed';a.style.left='-9999px';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000)}setMsg(`✅ Respaldo recibido (${(blob.size/1024/1024).toFixed(2)} MB): ${filename}. Si el navegador no lo guardó automáticamente, permití las descargas para este sitio y volvé a tocar Descargar JSON.`)}catch(e:any){setMsg(e.message)}};const dateText=(v:string)=>v?new Date(v).toLocaleDateString('es-AR',{day:'2-digit',month:'2-digit',year:'numeric'}):'Sin configurar';const isExpired=(x:any)=>!!x.expiresAt&&Date.now()>=Date.parse(x.expiresAt);const expiring=(x:any)=>!!x.expiresAt&&!isExpired(x)&&Date.parse(x.expiresAt)-Date.now()<=7*86400000;return <div className="adminPage"><div className="adminHead"><div><span className="eyebrow">CATÁLOGO FÁCIL · ADMINISTRACIÓN</span><h1>Administrar catálogos</h1><p>Aprobaciones, avisos de pago, vencimientos y copias de seguridad.</p></div></div><div className="adminLogin"><label>Clave administrativa<input type="password" value={key} onChange={e=>setKey(e.target.value)} placeholder="Clave configurada por el propietario"/></label><button className="primary" onClick={refresh}>Ingresar / actualizar</button></div>{msg&&<p className="adminMessage">{msg}</p>}<div className="clientGrid">{items.map(x=><article className={`clientCard ${x.status==='pending'?'clientPending':isExpired(x)||expiring(x)?'clientExpiring':''}`} key={x.slug}><div><span className="clientId">/{x.slug}</span><h3>{x.name}</h3><small>{x.status==='pending'?'PENDIENTE DE APROBACIÓN':x.status==='rejected'?'SOLICITUD RECHAZADA':isExpired(x)?'VENCIDO · PAUSADO':expiring(x)?'POR VENCER · REVISAR PAGO':x.status==='active'?'Activo':'Desactivado'} · {x.products||0} productos</small><p><b>Creado:</b> {dateText(x.createdAt)}<br/><b>Vence:</b> {dateText(x.expiresAt)}</p>{x.status==='pending'&&<div className="approvalActions"><b>Nuevo catálogo: ¿lo aprobás?</b><button className="primary" onClick={()=>setStatus(x,'active')}><CheckCircle2 size={15}/>Aprobar y publicar</button><button className="dangerBtn" onClick={()=>setStatus(x,'rejected')}>Rechazar</button></div>}{x.status==='rejected'&&<button className="primary" onClick={()=>setStatus(x,'active')}>Aprobar y activar</button>}<label className="adminDateLabel">Fecha de vencimiento<input type="date" value={adminDateValue(x.expiresAt)} onChange={e=>setDate(x,e.target.value)}/></label><div className="adminMonths"><button onClick={()=>setMonths(x,2)}>2 meses</button><button onClick={()=>setMonths(x,3)}>3 meses</button><button onClick={()=>setMonths(x,6)}>6 meses</button><button onClick={()=>setDate(x,'')}>Sin vencimiento</button></div><label className="adminDateLabel">Enviar alerta al catálogo<textarea value={alertDrafts[x.slug]||''} onChange={e=>setAlertDrafts(v=>({...v,[x.slug]:e.target.value}))} placeholder="Por favor efectuar pago WhatsApp 2615407856" rows={2}/></label><div className="alertActions"><button className="primary" onClick={()=>saveAlert(x)}>Enviar alerta</button><button className="secondary" onClick={()=>{setAlertDrafts(v=>({...v,[x.slug]:''}));void call('/admin/catalogs/alert','POST',{slug:x.slug,message:''}).then(()=>{void refresh();setMsg('Alerta quitada del catálogo.')}).catch((e:any)=>setMsg(e.message))}}>Quitar alerta</button></div><p><a href={`${window.location.pathname}?catalog=${encodeURIComponent(x.slug)}`} target="_blank" rel="noreferrer">Abrir catálogo</a></p></div><div className="clientActions"><button className="secondary" onClick={()=>setStatus(x,x.status==='active'?'disabled':'active')}>{x.status==='active'?'Desactivar':'Activar'}</button><button className="secondary" onClick={()=>exportJson(x)}>Descargar JSON</button><button className="dangerBtn" onClick={async()=>{if(!confirm(`¿Eliminar definitivamente “${x.name}”?`))return;try{await call('/admin/catalogs/delete','POST',{slug:x.slug});await refresh()}catch(e:any){setMsg(e.message)}}}>Eliminar</button></div></article>)}</div>{loaded&&!items.length&&<p>No hay catálogos registrados.</p>}<small className="privacyNote">Los catálogos nuevos quedan ocultos hasta aprobarlos. Los catálogos existentes conservan su estado y configuración.</small></div>}

function AIStudio({c,setC,initialProductId}:any){
 const [question,setQuestion]=useState('');const [result,setResult]=useState('');const [busy,setBusy]=useState(false);const [msg,setMsg]=useState('');const [selectedProductId,setSelectedProductId]=useState(initialProductId||'');const [conversation,setConversation]=useState<any[]>([]);const [lastQuestion,setLastQuestion]=useState('');
 useEffect(()=>{if(initialProductId){setSelectedProductId(initialProductId);setConversation([]);setResult('');setLastQuestion('')}},[initialProductId]);
 const selectedProduct=(c.products||[]).find((p:any)=>p.id===selectedProductId);
 const run=async(mode:'ask'|'refresh'='ask',overrideQuestion?:string)=>{const currentQuestion=(overrideQuestion??(mode==='refresh'?lastQuestion:question)).trim();if(!currentQuestion){setMsg('Escribí tu pregunta o pedido.');return}if(!API_BASE){setMsg('La IA todavía no está configurada. El administrador debe configurar el publicador de Cloudflare.');return}setBusy(true);setMsg('');try{const productContext=selectedProduct?{id:selectedProduct.id,name:selectedProduct.name,description:selectedProduct.description||'',price:Number(selectedProduct.price)||0,category:c.categories.find((x:any)=>x.id===selectedProduct.category)?.name||'Sin categoría',available:selectedProduct.available!==false,hasImage:!!selectedProduct.image,colors:selectedProduct.colors||[],sizes:selectedProduct.sizes||[]}:null;const history=mode==='refresh'?conversation.slice(0,-1):conversation;const prompt=mode==='refresh'?`Volvé a generar y mejorar tu última respuesta a esta misma consulta. No la cortes; desarrollá una respuesta completa, clara y útil. Consulta original: ${currentQuestion}`:currentQuestion;const r=await fetch(`${API_BASE}/ai/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,conversation:history.slice(-12),selectedProduct:productContext,catalog:{name:c.name,description:c.description,categories:c.categories,products:(c.products||[]).map((p:any)=>({name:p.name,description:p.description,category:c.categories.find((x:any)=>x.id===p.category)?.name||''})).slice(0,80)}})});let d:any={};try{d=await r.json()}catch{}if(!r.ok||!d.ok)throw new Error(d.error||`No se pudo conectar con GroqCloud (HTTP ${r.status}).`);const answer=String(d.text||'GroqCloud no devolvió una respuesta.');setResult(answer);setLastQuestion(currentQuestion);setConversation((old:any[])=>[...old,{role:'user',text:currentQuestion},{role:'assistant',text:answer}].slice(-12));if(d.truncated)setMsg('La respuesta alcanzó el límite de generación. Podés tocar “Continuar respuesta” para pedirle que siga desde donde quedó.');else setMsg('');if(mode==='ask')setQuestion('')}catch(e:any){setMsg(e.message||'No se pudo conectar con el asistente.')}finally{setBusy(false)}};
 const continueAnswer=()=>{if(!result||busy)return;const followUp='Continuá exactamente desde donde terminó la respuesta anterior, sin repetir lo ya explicado. Completá los puntos pendientes con el mismo nivel de detalle.';setQuestion('');void run('ask',followUp)};
 return <section className="aiStudio"><div className="aiHero"><div className="aiIcon"><Sparkles size={26}/></div><div><span className="eyebrow">ASISTENTE CON IA</span><h2>¿En qué te ayudo?</h2><p>Escribí lo que quieras consultar. Podés continuar la conversación, pedir aclaraciones o volver a generar una respuesta.</p></div></div><div className="aiForm"><label>Producto sobre el que querés consultar<select value={selectedProductId} onChange={e=>{setSelectedProductId(e.target.value);setConversation([]);setResult('');setLastQuestion('')}}><option value="">Consulta general (sin seleccionar producto)</option>{(c.products||[]).map((p:any)=><option key={p.id} value={p.id}>{p.name}{p.category?' — '+(c.categories.find((x:any)=>x.id===p.category)?.name||'') :''}</option>)}</select></label>{selectedProduct&&<div className="aiSelectedProduct"><b>{selectedProduct.name}</b><span>{c.categories.find((x:any)=>x.id===selectedProduct.category)?.name||'Sin categoría'}{Number(selectedProduct.price)>0?` · ${money(Number(selectedProduct.price),c.currency)}`:''}</span>{selectedProduct.description&&<p>{selectedProduct.description}</p>}</div>}<label>Tu pregunta o mensaje de seguimiento<textarea value={question} onChange={e=>setQuestion(e.target.value)} placeholder={conversation.length?'Escribí tu siguiente pregunta sobre la respuesta anterior…':selectedProduct?'Ej.: ¿Qué título le quedaría mejor a este producto? ¿Qué promoción puedo hacer?':'Ej.: Necesito ideas para crear promociones de pantalones azules'} rows={4} onKeyDown={e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();void run('ask')}}}/></label><button className="primary aiGenerate" onClick={()=>void run('ask')} disabled={busy}>{busy?<RefreshCw size={17} className="aiSpin"/>:<Sparkles size={17}/>} {busy?'Pensando…':'Preguntar a la IA'}</button>{msg&&<p className="aiMessage">{msg}</p>}</div><div className="aiResult"><div className="aiResultHead"><div><span className="eyebrow">RESPUESTA</span><h3>GroqCloud</h3></div><div className="aiResponseActions"><button className="secondary" disabled={!result||busy} onClick={()=>void navigator.clipboard?.writeText(result).then(()=>setMsg('Respuesta copiada.')).catch(()=>setMsg('No se pudo copiar automáticamente.'))}><CopyIcon size={15}/>Copiar</button><button className="secondary" disabled={!lastQuestion||busy} onClick={()=>void run('refresh')}><RefreshCw size={15}/>Regenerar</button><button className="secondary" disabled={!result||busy} onClick={continueAnswer}><ArrowUpRight size={15}/>Continuar respuesta</button></div></div><div className="aiResultText" style={{whiteSpace:'pre-wrap'}}>{result||'La respuesta aparecerá acá.'}</div></div></section>
}

function CatalogStudio(){
 const[c,setC]=useState<Catalog>(loadLocal),[tab,setTab]=useState<any>('products'),[cat,setCat]=useState('all'),[search,setSearch]=useState(''),[status,setStatus]=useState(''),[aiProductId,setAiProductId]=useState(''),[loadedSlug,setLoadedSlug]=useState(()=>{try{return localStorage.getItem('catalogo-facil-recovery-slug')||''}catch{return ''}}),[passwordModal,setPasswordModal]=useState(false),[catalogPassword,setCatalogPassword]=useState(''),[publishing,setPublishing]=useState(false);
 const changeTab=(next:any,replace=false)=>{setTab(next);const u=new URL(location.href);if(next==='products')u.searchParams.delete('editor');else u.searchParams.set('editor',next);(replace?history.replaceState:history.pushState).call(history,{editorTab:next},'',u)};
 useEffect(()=>{const x=new URL(location.href).searchParams.get('editor');if(['products','ai','design','settings','publish','preview'].includes(x||''))setTab(x);else setTab('products');const pop=()=>{const y=new URL(location.href).searchParams.get('editor');setTab(['products','ai','design','settings','publish','preview'].includes(y||'')?y:'products')};addEventListener('popstate',pop);return()=>removeEventListener('popstate',pop)},[]);
 useEffect(()=>{saveLocal(c);void storeCatalogDB(c).catch(e=>console.warn('No se pudo guardar copia IndexedDB:',e))},[c]);
 const visible=useMemo(()=>c.products.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())&&(cat==='all'||p.category===cat)),[c.products,search,cat]);
 const askAboutProduct=(productId:string)=>{setAiProductId(productId);changeTab('ai');window.setTimeout(()=>document.querySelector('.aiStudio')?.scrollIntoView({behavior:'smooth',block:'start'}),120)};
 const update=(x:Partial<Catalog>)=>setC(v=>({...v,...x}));
 const addProduct=()=>{const p:Product={id:uid(),name:'Nuevo producto',description:'',price:0,category:c.categories[0]?.id||'',image:'',available:true,usesVariants:false,sizes:[],colors:[]};setC(v=>({...v,products:[p,...v.products]}));changeTab('products')};
 const addCat=()=>{const x={id:uid(),name:'Nueva categoría',emoji:'📦'};setC(v=>({...v,categories:[...v.categories,x]}));setCat(x.id)};
 const file=(setter:(s:string)=>void)=>{const i=document.createElement('input');i.type='file';i.accept='image/*,.heic,.heif,.avif,.bmp,.tif,.tiff';i.onchange=()=>{const f=i.files?.[0];if(!f)return;void (async()=>{try{let blob:Blob=f;let bytes=new Uint8Array(await f.arrayBuffer());const starts=(a:number[])=>a.every((v,n)=>bytes[n]===v);let mime=f.type; if(starts([0xFF,0xD8,0xFF]))mime='image/jpeg';else if(starts([0x89,0x50,0x4E,0x47]))mime='image/png';else if(starts([0x47,0x49,0x46,0x38]))mime='image/gif';else if(bytes[0]===0x52&&bytes[1]===0x49&&bytes[2]===0x46&&bytes[3]===0x46&&bytes[8]===0x57&&bytes[9]===0x45&&bytes[10]===0x42&&bytes[11]===0x50)mime='image/webp';else if(bytes[0]===0x42&&bytes[1]===0x4D)mime='image/bmp';const head=new TextDecoder('ascii').decode(bytes.slice(0,64));const isHeic=/ftyp(heic|heix|hevc|hevx|mif1|msf1)/.test(head);if(isHeic){try{blob=await convertHeic(f);mime='image/jpeg'}catch{throw new Error('Este archivo es HEIC/HEIF y no se pudo convertir. En el teléfono, elegí compartir/guardar la foto como JPG y volvé a subirla.')}}else blob=new Blob([bytes],{type:mime||'application/octet-stream'});const url=URL.createObjectURL(blob);const img=new Image();img.onload=()=>{try{const max=1600,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));const cv=document.createElement('canvas');cv.width=w;cv.height=h;const ctx=cv.getContext('2d');if(!ctx)throw new Error('No se pudo procesar la imagen.');ctx.drawImage(img,0,0,w,h);const result=cv.toDataURL('image/webp',.84);URL.revokeObjectURL(url);if(!result||result==='data:,')throw new Error('La imagen no pudo convertirse.');setter(result)}catch(e){URL.revokeObjectURL(url);alert(e instanceof Error?e.message:'No se pudo procesar la imagen.');}};img.onerror=()=>{URL.revokeObjectURL(url);alert('No se pudo leer esta imagen. Probá con JPG, PNG, WEBP o HEIC/HEIF. Si es HEIC, verificá que la conversión esté incluida en esta versión.');};img.src=url}catch(e){alert(e instanceof Error?e.message:'No se pudo cargar la imagen.');}})()};i.click()};
 const slug=loadedSlug||slugify(c.name),publicUrl=`https://francoferrari9595-cod.github.io/CatalogoFacil/?catalog=${encodeURIComponent(slug)}`;
 const downloadJson=(data:string)=>{const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`${slug}.catalogo.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)};
 const exportData=async(autoPublish=false)=>{const cleaned=normalizeCatalog(c);setC(cleaned);const data=JSON.stringify({...cleaned,slug},null,2);if(!autoPublish){downloadJson(data);setStatus(`✓ Archivo guardado. Enlace público: ${publicUrl}`);return}setCatalogPassword('');setPasswordModal(true)};const confirmPublish=async()=>{if(catalogPassword.length<8){setStatus('La contraseña debe tener al menos 8 caracteres.');return}setPublishing(true);setStatus('⏳ Verificando propiedad y publicando catálogo…');try{const cleaned=normalizeCatalog(c);setC(cleaned);const result=await publishCatalog({...cleaned,slug},slug,catalogPassword);setLoadedSlug(slug);setStatus(result.status==='pending'?`⏳ Catálogo enviado al administrador para aprobación. El enlace quedará visible cuando lo aprueben: ${publicUrl}`:`✅ Catálogo publicado/actualizado. Enlace: ${publicUrl}`);setPasswordModal(false);setCatalogPassword('')}catch(e:any){setStatus(`❌ ${e?.message||'No se pudo publicar.'}`)}finally{setPublishing(false)}};
 const importData=()=>{const i=document.createElement('input');i.type='file';i.accept='.json,application/json,.catalogo.json';i.onchange=()=>{const f=i.files?.[0];if(!f)return;const r=new FileReader();r.onerror=()=>setStatus('❌ No se pudo leer el archivo. Probá descargarlo nuevamente y elegí el archivo JSON completo.');r.onload=()=>{try{const raw=JSON.parse(String(r.result));if(!raw||typeof raw!=='object'||(!Array.isArray(raw.products)&&!Array.isArray(raw.categories)))throw new Error('El JSON no tiene la estructura de un catálogo.');const restored=normalizeCatalog(raw);setC(restored);setLoadedSlug(String(raw.slug||slugify(raw.name||'catalogo')));setStatus(`✅ Respaldo cargado: ${restored.name||'Catálogo'} · ${restored.products.length} productos · ${restored.categories.length} categorías. No se descartaron registros del archivo.`);changeTab('products')}catch(e:any){setStatus(`❌ No se pudo cargar el respaldo: ${e?.message||'JSON inválido'}. El archivo original no fue modificado.`)}};r.readAsText(f,'UTF-8')};i.click()};
 const loadCloudCatalog=async()=>{const answer=prompt('Escribí el enlace del catálogo publicado o su identificador (slug). Ejemplo: pepperina-s-indumentaria',loadedSlug||slugify(c.name));if(!answer)return;let target=answer.trim();try{if(/^https?:\/\//i.test(target)){const u=new URL(target);target=u.searchParams.get('catalog')||u.pathname.match(/\/catalog\/([^/]+)/)?.[1]||u.pathname.split('/').filter(Boolean).pop()||''}}catch{}target=slugify(decodeURIComponent(target.replace(/^\/+|\/+$/g,'')));if(!target){setStatus('No pude reconocer el nombre del catálogo.');return}setStatus(`⏳ Cargando ${target} desde la nube…`);try{const remote=await loadPublishedCatalog(target);const cleaned=normalizeCatalog(remote);setC(cleaned);setLoadedSlug(target);setTab('products');const u=new URL(location.href);u.searchParams.delete('catalog');u.searchParams.delete('editor');history.replaceState({},'',u);setStatus(`✅ Catálogo “${cleaned.name}” cargado desde la nube con ${cleaned.products.length} productos. Ya podés editarlo y publicarlo desde cualquier dispositivo usando la contraseña del catálogo.`)}catch(e:any){setStatus(`❌ No se pudo cargar el catálogo “${target}”: ${e?.message||'Error de conexión'}`)}};
 return <div className="app"><aside><div className="brand"><div className="brandmark">✦</div><div><b>Catálogo Fácil</b><small className="brandBy">by Franco Ferrari</small></div></div><nav>{[['products','Productos',ShoppingBag],['design','Diseño',Palette],['settings','Negocio',Settings],['publish','Publicar',Globe],['preview','Vista previa',Eye]].map(([id,label,I])=><button className={tab===id?'active':''} onClick={()=>changeTab(id)} key={String(id)}><I size={18}/>{label}</button>)}</nav><div className="sideBottom"><button onClick={()=>void loadCloudCatalog()}><Globe size={17}/>Cargar catálogo de la nube</button><button onClick={importData}><Upload size={17}/>Cargar catálogo anterior</button></div></aside><main><div className="mobileBrand"><div className="brandmark">✦</div><div><b>Catálogo Fácil</b><small>by Franco Ferrari</small></div></div><header><div><span className="eyebrow">EDITOR DE CATÁLOGOS</span><h1>{tab==='home'?'Tu catálogo':tab==='products'?'Productos':tab==='ai'?'Estudio IA':tab==='design'?'Diseño':tab==='settings'?'Datos del negocio':tab==='publish'?'Publicar catálogo':'Vista previa'}</h1></div><div className="headerActions"><button className="secondary" onClick={()=>changeTab('preview')}><Eye size={17}/>Previsualizar</button><button className="primary" onClick={()=>changeTab('publish')}><Globe size={17}/>Publicar / actualizar</button></div></header><div className="mobileEditorNav" aria-label="Navegación del editor"><div className="mobileEditorTabs">{[['products','Productos',ShoppingBag],['design','Diseño',Palette],['settings','Negocio',Settings],['publish','Publicar',Globe],['preview','Vista previa',Eye]].map(([id,label,I])=><button className={tab===id?'active':''} onClick={()=>changeTab(id)} key={String(id)}><I size={16}/><span>{label}</span></button>)}</div><div className="mobileEditorActions"><button onClick={()=>void loadCloudCatalog()}><Globe size={15}/>Cargar de la nube</button><button onClick={importData}><Upload size={15}/>Cargar catálogo</button></div></div>{status&&<div className="tokenHelp"><CheckCircle2 size={16}/><span>{status}</span></div>}<div className="tabStage" key={tab}>{tab==='products'&&<Products c={c} setC={setC} cat={cat} setCat={setCat} visible={visible} search={search} setSearch={setSearch} addCat={addCat} file={file} onAskAI={askAboutProduct}/>} {tab==='ai'&&<AIStudio c={c} setC={setC} initialProductId={aiProductId}/>} {tab==='design'&&<Design c={c} update={update} setTab={changeTab}/>} {tab==='settings'&&<SettingsPanel c={c} update={update} file={file}/>} {tab==='publish'&&<Publish c={c} slug={slug} publicUrl={publicUrl} publish={()=>exportData(true)} status={status} setStatus={setStatus}/>} {tab==='preview'&&<Preview c={c}/>}</div></main>{passwordModal&&<div className="passwordOverlay" role="dialog" aria-modal="true" aria-labelledby="catalogPasswordTitle"><div className="passwordDialog"><div className="passwordIcon"><LockKeyhole size={24}/></div><span className="eyebrow">PROTECCIÓN DEL CATÁLOGO</span><h2 id="catalogPasswordTitle">{loadedSlug||'Catálogo nuevo'}{loadedSlug?' · actualizar':' · primera publicación'}</h2><p>{loadedSlug||slugify(c.name)}: {loadedSlug?'Ingresá la contraseña que creaste al publicarlo para autorizar cambios.':'Como este nombre todavía no tiene un catálogo registrado, elegí ahora una contraseña de al menos 8 caracteres. La vas a necesitar cada vez que quieras modificarlo.'}</p><label>Contraseña del catálogo<input autoFocus type="password" autoComplete="new-password" value={catalogPassword} onChange={e=>setCatalogPassword(e.target.value)} placeholder="Mínimo 8 caracteres" onKeyDown={e=>{if(e.key==='Enter')void confirmPublish()}}/></label><small>{catalogPassword.length}/8 caracteres mínimos</small><div className="passwordDialogActions"><button className="secondary" onClick={()=>setPasswordModal(false)} disabled={publishing}>Cancelar</button><button className="primary" onClick={()=>void confirmPublish()} disabled={publishing||catalogPassword.length<8}>{publishing?'Publicando…':'Autorizar y publicar'}</button></div></div></div>}</div>
}

function Publish({c,slug,publicUrl,publish,status,setStatus}:{c:Catalog,slug:string,publicUrl:string,publish:()=>void,status:string,setStatus:(s:string)=>void}){
 const data=JSON.stringify({...c,slug},null,2);
 const sendWhatsApp=async()=>{const message=`\u{1F6CD}\uFE0F ${c.name}\n${c.description||'Mirá nuestro catálogo'}\n\n${publicUrl}`;try{const imageSource=c.logo||c.cover;if(imageSource&&navigator.share){try{const response=await fetch(imageSource);const blob=await response.blob();const extension=(blob.type.split('/')[1]||'webp').replace('jpeg','jpg');const file=new File([blob],`${slug}-local.${extension}`,{type:blob.type||'image/webp'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:c.name,text:message});setStatus('✓ Compartiste el catálogo con la foto del local y el enlace.');return}}catch(e:any){if(e?.name==='AbortError')return;}}window.open(`https://wa.me/?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');setStatus(imageSource?'Se abrió WhatsApp con el nombre, la descripción y el enlace. Si el navegador no permite adjuntar la foto automáticamente, agregala en WhatsApp.':'Se abrió WhatsApp con el nombre y el enlace. Podés agregar la foto del local en el chat.')}catch{window.open(`https://wa.me/?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');setStatus('Se abrió WhatsApp con el enlace del catálogo.')}};
 const download=()=>{const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`${slug}.catalogo.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);setStatus('✓ Respaldo JSON guardado para futuras modificaciones.')};
 return <section className="publish"><div className="publishHero"><div><span className="pill">PUBLICACIÓN AUTOMÁTICA</span><h2>Publicá y obtené el enlace para tus clientes.</h2><p>La autorización de publicación ya está configurada. No tenés que conectar ni pegar ningún token en la web.</p></div><div className="publishIcon"><Globe size={44}/></div></div><div className="publishGrid"><div className="publishCard"><div className="formHead"><b>Publicación configurada</b><span>Lista para usar.</span></div><div className="publishPreview"><div className="check"><CheckCircle2 size={18}/><span>Publicación</span></div><span>Automática y sin token para el usuario</span></div><div className="publishPreview"><div className="check"><CheckCircle2 size={18}/><span>Almacenamiento</span></div><span>Seguro y separado del código público</span></div><p className="tokenNote">No aparece ningún campo de token. Al presionar publicar, Catálogo Fácil guarda el catálogo automáticamente.</p></div><div className="publishCard"><div className="formHead"><b>Publicar / actualizar</b><span>El nombre del catálogo genera el enlace. Si cargás un JSON anterior, se conserva su mismo enlace.</span></div><div className="slugPreview"><label>Nombre del enlace<input value={slug} readOnly/></label><small>https://{GH_OWNER}.github.io/{GH_REPO}/?catalog={slug}</small></div><button className="publishBig" onClick={publish}><Globe size={20}/>🚀 Publicar catálogo</button><div className="status">{status||'Presioná Publicar catálogo para actualizar el enlace público.'}</div><div className="successBox"><CheckCircle2 size={22}/><div><b>Enlace público</b><span>Este es el enlace que vas a enviar a tus clientes.</span><code>{publicUrl}</code><div className="buttonRow"><button className="primary" onClick={()=>window.open(publicUrl,'_blank')}><ExternalLink size={16}/>Abrir catálogo</button><button className="secondary" onClick={()=>void sendWhatsApp()}><WhatsAppIcon size={16}/>Enviar por WhatsApp</button><button className="secondary" onClick={download}><Download size={16}/>Guardar respaldo</button></div></div></div><DirectoryCheck api={API_BASE} slug={slug}/></div></div></section>
}
function Home({c,setTab,addProduct,importData}:any){return <section className="home"><div className="hero"><div><span className="pill">● Guardado automáticamente</span><h2>Creá un catálogo que<br/><em>se vea increíble.</em></h2><p>Editá productos, precios, fotos y diseño. Después publicalo y compartí un enlace único con tu cliente. Cuando cambies algo, simplemente volvé a publicar.</p><div className="heroBtns"><button className="primary" onClick={addProduct}><Plus size={18}/>Agregar producto</button><button className="secondary" onClick={importData}><Upload size={18}/>Cargar catálogo</button><button className="secondary" onClick={()=>setTab('publish')}><Globe size={18}/>Publicar</button></div></div><div className="phone"><div className="phoneScreen"><div className="cover" style={{backgroundImage:c.cover?`url(${c.cover})`:undefined}}><div className="shade"/><div className="miniLogo">{c.logo?<img src={c.logo}/>:<span>✦</span>}</div><div className="phoneText"><b>{c.name}</b><small>{c.description}</small></div></div><div className="miniProducts"><div/><div/><div/></div></div></div></div><div className="stats"><Card n={c.products.length} t="Productos"/><Card n={c.categories.length} t="Categorías"/><Card n={c.products.filter(p=>p.available).length} t="Disponibles"/><Card n={c.whatsapp?'✓':'—'} t="WhatsApp"/></div><div className="quick"><div><b>Listo para publicar</b><span>Completá los productos y publicá cuando estés listo.</span></div><button onClick={()=>setTab('publish')}>Configurar publicación <ArrowUpRight size={15}/></button></div></section>}

function Card({n,t}:any){return <div className="stat"><strong>{n}</strong><span>{t}</span></div>}

function Products({c,setC,cat,setCat,visible,search,setSearch,addCat,file,onAskAI}:any){return <section className="products"><div className="toolbar"><div className="search"><Search size={17}/><input placeholder="Buscar producto..." value={search} onChange={e=>setSearch(e.target.value)}/></div><button className="secondary" onClick={addCat}><Plus size={17}/>Categoría</button><button className="primary" onClick={()=>{const p={id:uid(),name:'Nuevo producto',description:'',price:0,category:c.categories[0]?.id||'',image:'',available:true,usesVariants:false,sizes:[],colors:[]};setC((v:any)=>({...v,products:[p,...v.products]}))}}><Plus size={17}/>Producto</button></div><div className="productHint">La foto queda separada de los campos para que nombre, descripción, precio y categoría siempre estén visibles.</div><div className="categories"><button className={cat==='all'?'selected':''} onClick={()=>setCat('all')}>Todos</button>{c.categories.map((x:Category)=><div className="categoryEditor" key={x.id}><input aria-label="Nombre de categoría" value={x.name} onChange={e=>setC((v:any)=>({...v,categories:v.categories.map((q:Category)=>q.id===x.id?{...q,name:e.target.value}:q)}))}/><button className={cat===x.id?'selected':''} onClick={()=>setCat(x.id)} title="Filtrar categoría">{x.emoji}</button><button className="iconBtn danger" title="Eliminar categoría" onClick={()=>{if(c.products.some((p:Product)=>p.category===x.id)&&!confirm(`La categoría “${x.name}” tiene productos. ¿Eliminarla y mover esos productos a Sin categoría?`))return;setC((v:any)=>({...v,categories:v.categories.filter((q:Category)=>q.id!==x.id),products:v.products.map((p:Product)=>p.category===x.id?{...p,category:''}:p)}));if(cat===x.id)setCat('all')}}><Trash2 size={15}/></button></div>)}</div><div className="productGrid">{visible.map((p:Product)=><ProductCard key={p.id} p={p} c={c} setC={setC} file={file} onAskAI={()=>onAskAI(p.id)}/>)}</div>{!visible.length&&<div className="empty"><ShoppingBag size={36}/><b>No hay productos todavía</b><span>Agregá tu primer producto para empezar.</span></div>}</section>}

function ProductCard({p,c,setC,file,onAskAI}:any){const [variantModalOpen,setVariantModalOpen]=useState(false);useEffect(()=>{if(!variantModalOpen)return;const prev=document.body.style.overflow;document.body.style.overflow='hidden';return ()=>{document.body.style.overflow=prev}},[variantModalOpen]);const [newColorName,setNewColorName]=useState('');const [newColorA,setNewColorA]=useState('#8b5cf6');const [newColorB,setNewColorB]=useState('#06b6d4');const [mixColors,setMixColors]=useState(false);const patch=(x:any)=>setC((v:any)=>({...v,products:v.products.map((q:Product)=>q.id===p.id?{...q,...x}:q)}));return <article className="pCard"><div className="pImage" onClick={()=>file((s:string)=>patch({image:s}))}>{p.image?<img src={p.image}/>:<><ImageIcon size={27}/><span>Subir foto</span></>}</div><div className="pBody"><label className="fieldLabel">Nombre del producto<input className="pName" value={p.name} onChange={e=>patch({name:e.target.value.toLocaleUpperCase('es')})}/></label><label className="fieldLabel">Descripción<textarea maxLength={200} value={(p.description||'').slice(0,200)} onChange={e=>patch({description:e.target.value.slice(0,200)})} placeholder="Escribí una descripción (máximo 200 caracteres)..."/> <small className="descriptionCounter">{Math.min(200,(p.description||'').length)}/200 caracteres</small></label><div className="pRow"><label className="fieldLabel priceLabel">Precio<input className="priceInput" type="number" min="0" step="0.01" value={p.price===0?'':String(p.price)} placeholder="0,00" onChange={e=>patch({price:e.target.value===''?0:Math.max(0,Number(e.target.value)||0)})}/></label><label className="availableLabel"><span>Disponible</span><label className="switch"><input type="checkbox" checked={p.available} onChange={e=>patch({available:e.target.checked})}/><i/></label></label></div><div className="variantEditor"><label className="variantToggle"><input type="checkbox" checked={!!p.usesVariants} onChange={e=>patch({usesVariants:e.target.checked})}/><span><b>Este producto utiliza talles y colores</b><small>Activá esta opción solo para prendas o artículos con variantes.</small></span></label>{p.usesVariants&&<><button type="button" className="openVariantConfig" onClick={()=>setVariantModalOpen(true)}>Configurar talles y colores <span>{(p.sizes||[]).length} talles · {(p.colors||[]).length} colores</span></button>{variantModalOpen&&createPortal(<div className="variantModalOverlay" onClick={()=>setVariantModalOpen(false)}><section className="variantModal" role="dialog" aria-modal="true" aria-label="Configurar talles y colores" onClick={e=>e.stopPropagation()}><header><div><small>VARIANTES DEL PRODUCTO</small><h3>Elegí talles y colores</h3></div><button type="button" aria-label="Cerrar" onClick={()=>setVariantModalOpen(false)}>×</button></header><div className="variantConfig"><div><b>Talles disponibles</b><div className="variantChoices">{['XS','S','M','L','XL','XXL','XXXL','Unitalla'].map(size=><label key={size} className={(p.sizes||[]).includes(size)?'picked':''}><input type="checkbox" checked={(p.sizes||[]).includes(size)} onChange={e=>patch({sizes:e.target.checked?[...(p.sizes||[]),size]:(p.sizes||[]).filter((v:string)=>v!==size)})}/>{size}</label>)}</div></div><div><b>Colores disponibles</b><div className="colorChoices">{[{n:'Negro',v:'#171717'},{n:'Blanco',v:'#ffffff'},{n:'Gris',v:'#9ca3af'},{n:'Rojo',v:'#ef4444'},{n:'Bordó',v:'#7f1d3f'},{n:'Rosa',v:'#f472b6'},{n:'Naranja',v:'#f97316'},{n:'Amarillo',v:'#facc15'},{n:'Verde',v:'#22c55e'},{n:'Verde oscuro',v:'#166534'},{n:'Celeste',v:'#38bdf8'},{n:'Azul',v:'#2563eb'},{n:'Azul marino',v:'#1e3a8a'},{n:'Violeta',v:'#8b5cf6'},{n:'Marrón',v:'#92400e'},{n:'Beige',v:'#d6c1a1'},{n:'Lila',v:'#c4b5fd'}].map(color=><label key={color.n} title={color.n} className={(p.colors||[]).includes(color.n)?'picked':''}><input type="checkbox" checked={(p.colors||[]).includes(color.n)} onChange={e=>patch({colors:e.target.checked?[...(p.colors||[]),color.n]:(p.colors||[]).filter((v:string)=>v!==color.n)})}/><i style={{background:color.v}}/><span>{color.n}</span></label>)}{(p.colorOptions||[]).map((color:any)=><label key={color.name} title={color.name} className={(p.colors||[]).includes(color.name)?'picked':''}><input type="checkbox" checked={(p.colors||[]).includes(color.name)} onChange={e=>patch({colors:e.target.checked?[...(p.colors||[]),color.name]:(p.colors||[]).filter((v:string)=>v!==color.name)})}/><i style={{background:color.gradient?`linear-gradient(120deg,${color.value},${color.value2||color.value})`:color.value}}/><span>{color.name}</span></label>)}</div><div className="customColorBox"><b>＋ Nuevo color</b><input aria-label="Nombre del color" placeholder="Nombre del color" value={newColorName} onChange={e=>setNewColorName(e.target.value)} /><div className="customColorPickers"><label>Color base<input aria-label="Color base" type="color" value={newColorA} onChange={e=>setNewColorA(e.target.value)}/></label><label className="mixColorToggle"><input type="checkbox" checked={mixColors} onChange={e=>setMixColors(e.target.checked)}/> Mezclar 2 colores</label>{mixColors&&<label>Segundo color<input aria-label="Segundo color" type="color" value={newColorB} onChange={e=>setNewColorB(e.target.value)}/></label>}</div><button type="button" className="addCustomColor" onClick={()=>{const name=newColorName.trim();if(!name){alert('Escribí un nombre para el color.');return}if((p.colorOptions||[]).some((v:any)=>v.name.toLowerCase()===name.toLowerCase())||['Negro','Blanco','Gris','Rojo','Bordó','Rosa','Naranja','Amarillo','Verde','Verde oscuro','Celeste','Azul','Azul marino','Violeta','Marrón','Beige','Lila'].some(v=>v.toLowerCase()===name.toLowerCase())){alert('Ya existe un color con ese nombre.');return}const opt={name,value:newColorA,value2:mixColors?newColorB:newColorA,gradient:mixColors};patch({colorOptions:[...(p.colorOptions||[]),opt],colors:[...(p.colors||[]),name]});setNewColorName('')}}>Guardar y seleccionar color</button></div></div><small>Podés marcar varios talles y varios colores. Se mostrarán como opciones al cliente.</small></div></section></div>,document.body)}</>}</div><div className="pFooter"><button type="button" className="productAIButton" title="Consultar a la IA sobre este producto" aria-label={`Consultar IA sobre ${p.name}`} onClick={onAskAI}><Sparkles size={16}/><span>IA</span></button><label className="categoryLabel">Categoría<select value={p.category} onChange={e=>patch({category:e.target.value})}><option value="">Sin categoría</option>{c.categories.map((x:Category)=><option value={x.id} key={x.id}>{x.name}</option>)}</select></label><button className="iconBtn danger" title="Eliminar producto" onClick={()=>setC((v:any)=>({...v,products:v.products.filter((q:Product)=>q.id!==p.id)}))}><Trash2 size={17}/></button></div></div></article>}

