 const fonts:[Font,string,string][]=[['system','Sistema','Segoe UI / sistema'],['inter','Inter','Moderna y neutra'],['montserrat','Montserrat','Geométrica y comercial'],['playfair','Playfair','Elegante y editorial'],['nunito','Nunito','Redondeada y amigable'],['space','Space Grotesk','Tecnológica y moderna'],['manrope','Manrope','Limpia y profesional'],['outfit','Outfit','Geométrica y moderna'],['dm','DM Sans','Simple y elegante'],['orbitron','Orbitron','Futurista y tecnológica'],['poppins','Poppins','Moderna y redondeada'],['roboto','Roboto','Clara y versátil'],['lato','Lato','Amable y legible'],['raleway','Raleway','Elegante y ligera'],['oswald','Oswald','Condensada y potente'],['rubik','Rubik','Geométrica y actual'],['quicksand','Quicksand','Suave y minimalista'],['comfortaa','Comfortaa','Redondeada y distintiva'],['bebas','Bebas Neue','Condensada · titulares potentes'],['anton','Anton','Impactante · cartelería'],['abril','Abril Fatface','Editorial de lujo · moda'],['cinzel','Cinzel','Clásica romana · elegante'],['cormorant','Cormorant Garamond','Serif refinada · boutique'],['lora','Lora','Serif cálida · muy legible'],['merriweather','Merriweather','Serif robusta · lectura cómoda'],['dmserif','DM Serif Display','Serif de contraste · gourmet'],['josefin','Josefin Sans','Geométrica vintage · fina'],['worksans','Work Sans','Neutra y profesional'],['syne','Syne','Moderna · personalidad de diseño'],['sora','Sora','Tecnológica · limpia'],['urbanist','Urbanist','Urbana y amable'],['lexend','Lexend','Ultra legible · moderna'],['bricolage','Bricolage Grotesque','Expresiva · actual'],['fraunces','Fraunces','Serif con carácter · artesanal'],['righteous','Righteous','Redondeada retro · divertida'],['audiowide','Audiowide','Futurista · ideal para neón'],['exo2','Exo 2','Tecnológica · deportiva'],['pacifico','Pacifico','Manuscrita · cálida y cercana']];
